import{z as i,x as A,o as e,c as s,q as E,j as r,D as B,d as n,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"市场分割与 NBBO","description":"","frontmatter":{"title":"市场分割与 NBBO","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/market-fragmentation.md","filePath":"quant/market-fragmentation.md","lastUpdated":1791063341000}'),d={name:"quant/market-fragmentation.md"};function p(m,a,h,u,c,N){const t=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=E('<h1 id="市场分割与-nbbo" tabindex="-1">市场分割与 NBBO <a class="header-anchor" href="#市场分割与-nbbo" aria-label="Permalink to &quot;市场分割与 NBBO&quot;">​</a></h1><div class="epigraph"><p>同一只股票同时在许多场所报价和成交。全国最优买卖不是自然物体，是把各场所保护报价按规则拼出来的参照，拼的时钟和尺寸规则会改变「最优」二字。</p><footer>—— O&#39;Hara and Ye, Is Market Fragmentation Harming Market Quality?, Journal of Financial Economics, 2011；对照 Reg NMS 对保护报价与订单保护的制度表述</footer></div><p><a href="/quant/dark-pool-midpoint">暗池与中点单</a>把一部分匹配移出展示簿。<a href="/quant/lot-size-odd-lot">手数</a>说明保护报价可以不含零股。本课把多场所收成系统：碎片化（fragmentation）下，投资者面对的不是一张 <a href="/quant/lob-structure">LOB</a>，而是一簇场所加上一个拼装出来的 NBBO。O&#39;Hara 与 Ye 问碎片化是否损害质量；Foucault、Kadan、Kandel 与后续路由文献问订单如何在场所间分配。附录里的 <a href="/quant/nbbo-construction">NBBO 构造</a>会把磁带对齐写细；本课写设计层：为什么需要一个全国最优、它保护什么、以及有效价差该对照哪一个中点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单场所课程序把 BBO 当成给定。多场所时，每个交易所、每个 ATS 有自己的 BBO（或没有 BBO）。Reg NMS 一类规则要求：保护报价上的订单不能以劣于另一场所保护报价的价格成交（订单保护 / trade-through 限制），于是系统需要一个全国最优买卖 NBBO \\(=(\\max b_i, \\min a_i)\\)。缺口是：这个 \\(\\max\\) 与 \\(\\min\\) 用哪一时戳、哪些尺寸、是否含锁定与交叉。锁定（lock）是买价等于另一场所卖价，交叉（cross）是买价高于另一场所卖价。碎片化加上延迟，锁定交叉会经常出现在某一条馈送上，而不出现在另一条上。</p><p><span class="marginnote">NBBO（全国最优买卖报价）不是某一家交易所的报价，而是把全美十几家交易所各自展示的最优买价、最优卖价收上来，取「最高的买价」和「最低的卖价」拼成的一个参照数。可以把它想象成比价网站：商品还是那些商品，但「全国最低价」是算出来的，本身不开店。</span></p><p>若研究用 SIP 的 NBBO，得到的是监管参照；若用直连拼装的「合成 NBBO」，得到的是更快但不一定受保护的参照。两者的中点可以差一个 tick，有效价差符号可以翻转。问题不是选一个「真」中点，而是声明对照的是保护 NBBO 还是可交易的合成最优，并且承认碎片化把价差分解的对象从一张簿变成了一个规则输出。</p><h3 id="碎片化的质量是哪一类质量" tabindex="-1">碎片化的质量是哪一类质量 <a class="header-anchor" href="#碎片化的质量是哪一类质量" aria-label="Permalink to &quot;碎片化的质量是哪一类质量&quot;">​</a></h3><p>O&#39;Hara–Ye 用有效价差、实现价差、短时波动来谈质量。碎片化可能通过竞争压窄价差，也可能把深度拆薄、把时间优先拆到多条队列。做市商必须同时在多处维护报价，存货与撤单同步成本上升。暗份额上升时，展示 NBBO 可以很窄但可成交深度很小。因此「NBBO 价差变窄」不是充分统计量。还要看：保护深度、内部化份额、锁定交叉频率、以及跨场所的价差离散。</p><p><span class="marginnote">A 股竞价主板在连续时段基本是单一撮合，碎片化主要出现在港股、中美双重上市、以及期货–ETF–股票之间，而不是十几家股票交易所并行。把美股 NBBO 文献的数字当 A 股盘中成本，制度对象错了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>构造每日每秒（或每事件）的保护 NBBO，记录贡献场所、是否锁定交叉、以及相对本所 BBO 的偏离。有效价差对照保护中点；另报对照本所中点，差额即路由与碎片化造成的参照差。Hasbrouck 信息份额或领先后滞后，用来看哪一场所的报价新息写入「共同有效价格」——注意暗池没有报价，份额会系统性偏向展示场所。</p><p>路由仿真（不是实盘抢跑说明书）应服从公开的订单保护：以劣于 NBBO 的价格吃本所，在规则下应被拒绝或被转发出去。回测若在本所吃穿 NBBO 而不付转发延迟，实施缺口被低估。费用见<a href="/quant/maker-taker">maker-taker</a>：最窄的保护卖价未必是经济上最便宜的场所。</p><p><span class="marginnote">订单保护可以类比成「全国最低价承诺」：你在 A 店下单买某商品，若 B 店同款标价更便宜，系统不允许 A 店按高价成交——要么把订单转去 B 店的价格，要么拒绝执行。这一条规则是把十几家分散的交易所「绑」成一个虚拟统一市场的关键。</span></p><h3 id="锁定、交叉与过时的「最优」" tabindex="-1">锁定、交叉与过时的「最优」 <a class="header-anchor" href="#锁定、交叉与过时的「最优」" aria-label="Permalink to &quot;锁定、交叉与过时的「最优」&quot;">​</a></h3><p>直连比 SIP 快时，本地看到的最优可能已经不是 SIP 的 NBBO。交易所以本地所见为据，监管以 SIP 为据，两套最优短暂分叉。研究应报告分叉时间占比。交叉若被允许存在于暗处或零售通道，公开 NBBO 仍显示未交叉的保护报价。把所有 BBO 内成交当规则违反，会把合法的内部化、零股和中点标成异常。</p><p><span class="marginnote">用数字看锁定：假设某股票在 A 场所卖价挂 100.01，B 场所刚把买价提到 100.01——买价「追平」卖价就是锁定；若提到 100.02 则是交叉。这一瞬间在毫秒级的直连馈送上一眼可见，而慢半拍的 SIP 上 NBBO 还显示旧的未锁定状态，于是两条数据流「各说各话」。</span></p>',17)),(e(),r(l,null,{default:B(()=>[o(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20direct%5B%22%E7%9B%B4%E8%BF%9E%E9%A6%88%E9%80%81(%E5%BF%AB)%22%5D%0A%20%20%20%20D1%5B%22%E6%9C%AC%E6%89%80%20BBO%20%E5%8D%B3%E6%97%B6%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20D2%5B%22%E6%9C%AC%E5%9C%B0%E6%9C%80%E4%BC%98%E5%B7%B2%E5%8F%98%22%5D%0A%20%20end%0A%20%20subgraph%20sip%5B%22SIP%20%E9%A6%88%E9%80%81(%E6%85%A2)%22%5D%0A%20%20%20%20S1%5B%22%E4%BB%96%E5%9C%BA%E6%89%80%E6%8A%A5%E4%BB%B7%E6%85%A2%E5%8D%8A%E6%8B%8D%E4%BC%A0%E6%92%AD%22%5D%20--%3E%20S2%5B%22NBBO%20%E4%BB%8D%E6%98%AF%E6%97%A7%E4%BB%B7%22%5D%0A%20%20end%0A%20%20D2%20--%3E%20LK%7B%22%E4%B9%B0%E4%BB%B7%E8%BF%BD%E4%B8%8A%E5%8F%A6%E4%B8%80%E5%9C%BA%E6%89%80%E5%8D%96%E4%BB%B7%3F%22%7D%0A%20%20S2%20--%3E%20LK%0A%20%20LK%20--%3E%7C%22%E6%97%B6%E6%88%B3%E7%AA%97%E5%86%85%E5%87%BA%E7%8E%B0%22%7C%20LOCK%5B%22%E9%94%81%E5%AE%9A%2F%E4%BA%A4%E5%8F%89%E7%8A%B6%E6%80%81%22%5D%0A%20%20LK%20--%3E%7C%22%E6%9B%B4%E6%96%B0%E9%80%81%E8%BE%BE%E5%90%8E%E6%B6%88%E5%A4%B1%22%7C%20FINE%5B%22%E7%9E%AC%E6%97%B6%E7%8E%B0%E8%B1%A1%2C%20%E9%9D%9E%E8%BF%9D%E8%A7%84%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>订单保护把各场所的保护报价连成一个虚拟的全国簿，但这个簿没有统一的时间优先：同样的价格在两个场所是两条队列。竞争压缩展示价差；分割稀释每条队列的长度。知情交易可以选择在深度更厚或更暗的场所执行，非知情的展示做市商承担的逆向选择随分割变化。这与 <a href="/quant/glosten-milgrom">Glosten-Milgrom</a> 的单一专家设定不同：现在有一群场所，信念更新不同步。</p><p>NBBO 中点作为公共锚，供给暗池中点协议使用。碎片化越严重、SIP 越慢，锚越容易过时，中点成交的「公平」越弱。于是市场设计的三个旋钮绑在一起：tick 与手数定义保护报价，费用定义路由激励，碎片化定义有多少张簿需要被拼成一个最优。</p><p><span class="marginnote">不要把 <a href="/quant/kyle-model">Kyle</a> 的单市场 \\(\\lambda\\) 直接加总成「全国 lambda」。各场所 \\(y\\) 相关，价格是共同的。应先合成全国流量再回归，或明确只估本所弹性。</span></p>',4)),(e(),r(l,null,{default:B(()=>[o(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TB%0A%20%20V1%5B%22%E5%9C%BA%E6%89%80%20A%20%E4%BF%9D%E6%8A%A4%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20N%5B%22%E8%A7%84%E5%88%99%E6%8B%BC%E8%A3%85%20NBBO%22%5D%0A%20%20V2%5B%22%E5%9C%BA%E6%89%80%20B%20%E4%BF%9D%E6%8A%A4%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20N%0A%20%20V3%5B%22%E6%9A%97%E6%B1%A0%E6%97%A0%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20T%5B%22%E7%A3%81%E5%B8%A6%E6%88%90%E4%BA%A4%22%5D%0A%20%20N%20--%3E%20M%5B%22%E4%BF%9D%E6%8A%A4%E4%B8%AD%E7%82%B9%22%5D%0A%20%20M%20--%3E%20ES%5B%22%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%E5%AF%B9%E7%85%A7%22%5D%0A%20%20T%20--%3E%20ES%0A%20%20N%20--%3E%20R%5B%22%E8%AE%A2%E5%8D%95%E4%BF%9D%E6%8A%A4%E4%B8%8E%E8%B7%AF%E7%94%B1%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h3 id="费用调整后的最优不必等于保护最优" tabindex="-1">费用调整后的最优不必等于保护最优 <a class="header-anchor" href="#费用调整后的最优不必等于保护最优" aria-label="Permalink to &quot;费用调整后的最优不必等于保护最优&quot;">​</a></h3><p>保护卖价最窄的场所，加上 taker 费可能不是经济最便宜。NBBO 管订单保护，不管经济价差。路由研究必须两套最优并排，否则会把收费方案当成碎片化损害。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>欧洲是另一套最佳执行与透明制度，没有美国式的单一 SIP NBBO。新兴市场的「分割」常常是官方市场加场外大宗，而不是一打注册交易所。本课不写如何利用 SIP 延迟做跨场所套利的操作步骤；那是附录延迟套利的对象。本课只要求：价差、深度、方向分类，在碎片化样本里必须声明报价源。</p><p><span class="marginnote">没有 SIP 的市场不要把「你覆盖的几张簿的包络」叫 NBBO。那是研究构造，没有订单保护的法律含义。</span></p><p>市场设计这一课序到此收束。下一课序价格形成从 <a href="/quant/roll-model">Roll</a> 起，用成交回跳读有效价差；默认你已经知道，连续段的 \\(s\\) 是某一套协议与某一套保护报价的输出，不是自然宽度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NBBO 是保护报价按规则的拼装，不是一张真实的统一簿。</li><li>对照 SIP 中点还是直连合成中点，有效价差可以变号。</li><li>碎片化可能压窄价差同时拆薄深度；质量要用多指标。</li><li>锁定交叉、零股、暗池内部成交，使「BBO 内」不等于违规。</li><li>单市场价差分解与 Kyle lambda 在多场所必须重定义流量与价格。</li><li>出处：O&#39;Hara and Ye, <em>JFE</em>, 2011；Reg NMS 公开规则；Hasbrouck 对多市场价格发现的度量；Angel, Harris and Spatt 对美国股权市场结构的综述。</li></ul>',8))])}const D=i(d,[["render",p]]);export{O as __pageData,D as default};
